window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8349646e9cd541d8"]={"versions": [{"id": "FIG-8349646e9cd541d8", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Feature-Diagramm / Feature-Baum (Feature-Oriented Domain Analysis, FODA-Notation).\n</li><li><strong>Technischer Zweck:</strong> Das Diagramm <code>Figure 4.2: AR_Features</code> aus dem Foundation-Dokument <code>AUTOSAR_FO_TR_Features</code> (Release R24-11) stellt die oberste Ebene der hierarchischen Feature-Dekompensation der AUTOSAR-Plattformen (Classic Platform, Adaptive Platform und Foundation) dar.\n</li><li><strong>Funktionale Einordnung:</strong> Dient als systemweites, formales Klassifikations- und Traceability-Framework zur Strukturierung funktionaler Anforderungen (<code>RS_FO_*</code>, <code>RS_SAF_*</code>, etc.) und zur Zuordnung standardisierter BSW- bzw. ARA-Module zu übergeordneten Domänen.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzelknoten (Root Feature):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00042</code> (<code>AUTOSAR_Features</code>): Repräsentiert die Gesamtheit aller standardisierten AUTOSAR-Funktionalitäten.\n</li></ul>\n</li><li><strong>Mandatory Sub-Feature (Solider Kreis <code>●</code>):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00064</code> (<code>Basic_Functionality</code>): Obligatorische Basisfunktionalität (z. B. OS-Grundlagen, EcuM, BswM, Basisdienste). Eine konforme AUTOSAR-Instanz erfordert zwingend dieses Feature.\n</li></ul>\n</li><li><strong>Optional Sub-Features (Hohle Kreise <code>○</code>):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00111</code> (<code>Development</code>): Debug-, Trace-, Profiling- und Test-Hooks (z. B. DET, DLT, Core Test).\n</li><li><code>FO_TR_FEAT_00086</code> (<code>Diagnostic</code>): UDS-, DoIP- und Fehlerspeichermechanismen (DCM, DEM, FIM bzw. <code>ara::diag</code>).\n</li><li><code>FO_TR_FEAT_00096</code> (<code>Standardized_Application_Interface</code>): Standardisierte Port-Interfaces und Applikationsdatentypen.\n</li><li><code>FO_TR_FEAT_00222</code> (<code>Platform_Update</code>): Software-Aktualisierung / OTA / UCM (Update and Configuration Management).\n</li><li><code>FO_TR_FEAT_00043</code> (<code>Safety</code>): ISO-26262-Mechanismen (E2E-Protection, WdgM, Program Flow Monitoring, Core Self-Test).\n</li><li><code>FO_TR_FEAT_00055</code> (<code>Storage</code>): Nichtflüchtiger Speicherzugriff (NvM, Fee/Ea, MemIf bzw. <code>ara::per</code>).\n</li><li><code>FO_TR_FEAT_00071</code> (<code>Execution_Environment</code>): Laufzeitumgebung (RTE / VFB bzw. <code>ara::exec</code> / OS Application Partitioning).\n</li><li><code>FO_TR_FEAT_00207</code> (<code>Security</code>): Kryptografische Dienste, Key Storage, sichere On-Board-Kommunikation (CSM, CryIf, SecOC, KeyM bzw. <code>ara::crypto</code>).\n</li><li><code>FO_TR_FEAT_00122</code> (<code>Communication</code>): Bus- und Netzwerk-Kommunikationsstacks (CAN, LIN, FlexRay, Ethernet, SOME/IP).\n</li><li><code>FO_TR_FEAT_00236</code> (<code>Hardware_Support_IO</code>): Microcontroller Abstraction Layer (MCAL) und I/O-Hardwareabstraktion (DIO, ADC, PWM, ICU, SPI).\n</li></ul>\n</li><li><strong>Kardinalitäten &amp; Beziehungen:</strong>\n<ul class=\"fig-list\"><li>1:n hierarchische Kompositionsbeziehung vom Wurzel-Feature zu den Domänen-Features.\n</li><li>1 mandatory Feature, 10 optionale Features für die statische Systemkonfiguration.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Entfällt (Struktur-/Taxonomie-Modell):</strong>\n<ul class=\"fig-list\"><li>Das Diagramm definiert rein statische Domänen-Dekompensationen ohne Ausführungssemantik, Signalflüsse, Zustandsübergänge oder Callbacks.\n</li><li>Keine Laufzeit-Interaktionen, Scheduling-Trigger oder API-Aufrufe.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Systemkonfiguration &amp; Variantenmanagement:</strong>\n<ul class=\"fig-list\"><li>Das Feature-Modell steuert die High-Level-Validierung von BSW-Stacks und Plattform-Derivaten.\n</li><li>Nur <code>FO_TR_FEAT_00064</code> ist für jedes AUTOSAR-Target verpflichtend; alle weiteren Domänen werden selektiv über Pre-Compile-Schalter bzw. EcuExtract/ARXML projektiert.\n</li></ul>\n</li><li><strong>Traceability &amp; Conformance:</strong>\n<ul class=\"fig-list\"><li>Die IDs (<code>FO_TR_FEAT_xxxxx</code>) dienen im Release R24-11 als Bindeglied in Requirements-Management-Tools (ReqIF/DOORS) zwischen den AUTOSAR Acceptance Tests (AAT), System Requirements (SRS) und den Software-Spezifikationen (SWS).\n</li></ul>\n</li><li><strong>Relevanz für Stack- und Integrations-Entwickler:</strong>\n<ul class=\"fig-list\"><li>Definiert die funktionale Entkopplung der Module. Abhängigkeiten zwischen den Domänen (z. B. <code>Safety</code> → <code>Storage</code> für E2E-geschützte NvM-Daten) müssen in den untergeordneten SWS-Spezifikationen über wohldefinierte Schnittstellen aufgelöst werden, ohne zyklische BSW-Modulabhängigkeiten zu erzeugen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-54b07b7d84e9d4e4", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Feature-Diagramm / Feature-Baum (Feature-Oriented Domain Analysis, FODA-Notation).\n</li><li><strong>Technischer Zweck:</strong> Das Diagramm <code>Figure 4.2: AR_Features</code> aus dem Foundation-Dokument <code>AUTOSAR_FO_TR_Features</code> (Release R25-11) stellt die oberste Ebene der hierarchischen Feature-Dekompensation der AUTOSAR-Plattformen (Classic Platform, Adaptive Platform und Foundation) dar.\n</li><li><strong>Funktionale Einordnung:</strong> Dient als systemweites, formales Klassifikations- und Traceability-Framework zur Strukturierung funktionaler Anforderungen (<code>RS_FO_*</code>, <code>RS_SAF_*</code>, etc.) und zur Zuordnung standardisierter BSW- bzw. ARA-Module zu übergeordneten Domänen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Wurzelknoten (Root Feature):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00042</code> (<code>AUTOSAR_Features</code>): Repräsentiert die Gesamtheit aller standardisierten AUTOSAR-Funktionalitäten.\n</li></ul>\n</li><li><strong>Mandatory Sub-Feature (Solider Kreis <code>●</code>):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00064</code> (<code>Basic_Functionality</code>): Obligatorische Basisfunktionalität (z. B. OS-Grundlagen, EcuM, BswM, Basisdienste). Eine konforme AUTOSAR-Instanz erfordert zwingend dieses Feature.\n</li></ul>\n</li><li><strong>Optional Sub-Features (Hohle Kreise <code>○</code>):</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00111</code> (<code>Development</code>): Debug-, Trace-, Profiling- und Test-Hooks (z. B. DET, DLT, Core Test).\n</li><li><code>FO_TR_FEAT_00096</code> (<code>Standardized_Application_Interface</code>): Standardisierte Port-Interfaces und Applikationsdatentypen.\n</li><li><code>FO_TR_FEAT_00055</code> (<code>Storage</code>): Nichtflüchtiger Speicherzugriff (NvM, Fee/Ea, MemIf bzw. <code>ara::per</code>).\n</li><li><code>FO_TR_FEAT_00256</code> (<code>Timing</code>): Timing-Erweiterungen, Synchronisation und Zeitanforderungen (z. B. StbM, Timing Extensions / TIMEX).\n</li><li><code>FO_TR_FEAT_00086</code> (<code>Diagnostic</code>): UDS-, DoIP- und Fehlerspeichermechanismen (DCM, DEM, FIM bzw. <code>ara::diag</code>).\n</li><li><code>FO_TR_FEAT_00236</code> (<code>Hardware_Support</code>): Microcontroller Abstraction Layer (MCAL) und Hardwareabstraktion.\n</li><li><code>FO_TR_FEAT_00207</code> (<code>Security</code>): Kryptografische Dienste, Key Storage, sichere On-Board-Kommunikation (CSM, CryIf, SecOC, KeyM bzw. <code>ara::crypto</code>).\n</li><li><code>FO_TR_FEAT_00043</code> (<code>Safety</code>): ISO-26262-Mechanismen (E2E-Protection, WdgM, Program Flow Monitoring, Core Self-Test).\n</li><li><code>FO_TR_FEAT_00071</code> (<code>Execution_Environment</code>): Laufzeitumgebung (RTE / VFB bzw. <code>ara::exec</code> / OS Application Partitioning).\n</li><li><code>FO_TR_FEAT_00122</code> (<code>Communication</code>): Bus- und Netzwerk-Kommunikationsstacks (CAN, LIN, FlexRay, Ethernet, SOME/IP).\n</li><li><code>FO_TR_FEAT_00222</code> (<code>Software_Update</code>): Software-Aktualisierung / OTA / UCM (Update and Configuration Management).\n</li></ul>\n</li><li><strong>Kardinalitäten &amp; Beziehungen:</strong>\n<ul class=\"fig-list\"><li>1:n hierarchische Kompositionsbeziehung vom Wurzel-Feature zu den Domänen-Features.\n</li><li>1 mandatory Feature, 11 optionale Features für die statische Systemkonfiguration.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Entfällt (Struktur-/Taxonomie-Modell):</strong>\n<ul class=\"fig-list\"><li>Das Diagramm definiert rein statische Domänen-Dekompensationen ohne Ausführungssemantik, Signalflüsse, Zustandsübergänge oder Callbacks.\n</li><li>Keine Laufzeit-Interaktionen, Scheduling-Trigger oder API-Aufrufe.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Systemkonfiguration &amp; Variantenmanagement:</strong>\n<ul class=\"fig-list\"><li>Das Feature-Modell steuert die High-Level-Validierung von BSW-Stacks und Plattform-Derivaten.\n</li><li>Nur <code>FO_TR_FEAT_00064</code> ist für jedes AUTOSAR-Target verpflichtend; alle weiteren Domänen werden selektiv über Pre-Compile-Schalter bzw. EcuExtract/ARXML projektiert.\n</li></ul>\n</li><li><strong>Traceability &amp; Conformance:</strong>\n<ul class=\"fig-list\"><li>Die IDs (<code>FO_TR_FEAT_xxxxx</code>) dienen im Release R25-11 als Bindeglied in Requirements-Management-Tools (ReqIF/DOORS) zwischen den AUTOSAR-Anforderungsdokumenten und Spezifikationen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8349646e9cd541d8", "to": "FIG-54b07b7d84e9d4e4", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Neues optionales Sub-Feature <code>FO_TR_FEAT_00256</code> (<code>Timing</code>) unter <code>FO_TR_FEAT_00042</code> hinzugefügt.\n</li><li>Sub-Feature <code>FO_TR_FEAT_00236</code> von <code>Hardware_Support_IO</code> in <code>Hardware_Support</code> umbenannt.\n</li><li>Sub-Feature <code>FO_TR_FEAT_00222</code> von <code>Platform_Update</code> in <code>Software_Update</code> umbenannt und an das rechte Ende der Hierarchieebene verschoben.\n</li><li>Neuanordnung der Kindknoten unter <code>FO_TR_FEAT_00042</code> in der horizontalen Abfolge von links nach rechts.\n</li></ul>"}]};
